<template>
  <view class="page"><jk-page-nav title="线下销售"/><view class="content"><view class="toolbar"><text>终端销售记录</text><button @tap="goCreate">登记销售</button></view><view v-for="item in list" :key="item.id" class="card" @tap="open(item)"><view class="head"><text>{{item.saleNo}}</text><jk-status-tag :text="statusText(item)" :tone="tone(item.status)"/></view><view class="amount">¥{{money(item.totalAmount)}}</view><view class="line"><text>客户类型</text><text>{{item.customerType}}</text></view><view class="line"><text>销售时间</text><text>{{item.saleTime}}</text></view><view class="line"><text>经营毛利</text><text>¥{{money(item.totalProfitAmount)}}</text></view></view><jk-empty v-if="loaded&&!list.length" text="暂无线下销售记录"/><view v-if="hasMore" class="more" @tap="more">加载更多</view></view></view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkStatusTag from '@/components/jk/jk-status-tag.vue';import JkEmpty from '@/components/jk/jk-empty.vue';import{getJkOfflineSaleList}from'@/api/jkV31.js';
export default{components:{JkPageNav,JkStatusTag,JkEmpty},data(){return{page:1,limit:20,total:0,list:[],loaded:false}},computed:{hasMore(){return this.list.length<this.total}},onShow(){this.page=1;this.list=[];this.load()},methods:{value(r){return(r&&r.data)||r||{}},load(){this.loaded=false;getJkOfflineSaleList({page:this.page,limit:this.limit}).then(r=>{const d=this.value(r),rows=d.list||d.records||[];this.total=Number(d.total||rows.length);this.list=this.page===1?rows:this.list.concat(rows)}).finally(()=>this.loaded=true)},more(){this.page++;this.load()},money(v){return Number(v||0).toFixed(2)},statusText(i){return i.status==='PENDING_AUDIT'?'待后台审核':i.status==='CONFIRMED'?'已确认':i.status==='AUDIT_REJECTED'?'审核驳回':i.status==='PARTIALLY_RETURNED'?'部分退货':i.status==='RETURNED'?'已退货':i.status},tone(s){return s==='CONFIRMED'?'success':s==='PENDING_AUDIT'?'warning':s==='AUDIT_REJECTED'||s==='CANCELLED'?'danger':'info'},goCreate(){uni.navigateTo({url:'/pages/jk/offlineSale/create'})},open(i){uni.navigateTo({url:'/pages/jk/offlineSale/detail?id='+i.id})}}}
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:18rpx}.toolbar>text{font-size:30rpx;font-weight:700}.toolbar button{height:60rpx;margin:0;padding:0 24rpx;border-radius:30rpx;background:#16b990;color:#fff;font-size:22rpx;line-height:60rpx}.toolbar button::after{border:0}.card{margin-bottom:16rpx;padding:24rpx;border-radius:20rpx;background:#fff}.head,.line{display:flex;justify-content:space-between}.head>text{font-size:25rpx;font-weight:700}.amount{margin:18rpx 0;color:#11aa82;font-size:40rpx;font-weight:700}.line{margin-top:10rpx;color:#7c878c;font-size:22rpx}.line text:last-child{color:#3e4b51}.more{text-align:center;padding:24rpx;color:#11a981}</style>
